param()
$ErrorActionPreference='Stop';$root=Join-Path $env:LOCALAPPDATA 'AgentPlatform/adjudication-model-v1/product-runtime'
function AdjSecret([string]$file){$s=Import-Clixml -LiteralPath $file;$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}}
Add-Type -TypeDefinition @"
using System;using System.Net.Http;using System.Net.Security;using System.Security.Cryptography.X509Certificates;
public static class AdjDeploymentTrust { public static X509Certificate2 Root; public static readonly Func<HttpRequestMessage,X509Certificate2,X509Chain,SslPolicyErrors,bool> Callback=Validate; public static bool Validate(HttpRequestMessage r,X509Certificate2 c,X509Chain ignored,SslPolicyErrors e) {if(r.RequestUri.Scheme!="https"||r.RequestUri.Host!="localhost"||r.RequestUri.Port!=5445||c==null||(e&SslPolicyErrors.RemoteCertificateNameMismatch)!=0)return false;using(var chain=new X509Chain()){chain.ChainPolicy.TrustMode=X509ChainTrustMode.CustomRootTrust;chain.ChainPolicy.CustomTrustStore.Add(Root);chain.ChainPolicy.RevocationMode=X509RevocationMode.NoCheck;return chain.Build(c);}} }
"@
[AdjDeploymentTrust]::Root=[Security.Cryptography.X509Certificates.X509Certificate2]::new("$root/root-ca.cer")
function AdjClient([bool]$maintenance){$h=[Net.Http.HttpClientHandler]::new();$h.AllowAutoRedirect=$false;$h.UseCookies=$true;$h.CookieContainer=[Net.CookieContainer]::new();$h.SslProtocols=[Security.Authentication.SslProtocols]::Tls12;$h.ServerCertificateCustomValidationCallback=[AdjDeploymentTrust]::Callback;if($maintenance){$h.ClientCertificates.Add([Security.Cryptography.X509Certificates.X509Certificate2]::new("$root/maintainer.p12",(AdjSecret "$root/tls.credential.xml"),[Security.Cryptography.X509Certificates.X509KeyStorageFlags]::UserKeySet))|Out-Null};[Net.Http.HttpClient]::new($h)}
$maintenance=AdjClient $true;$member=AdjClient $false;$base='https://localhost:5445';$trace=[Collections.Generic.List[object]]::new()
function AdjSend($client,[string]$method,[string]$path,$body,[string]$key,[string]$token,[int]$expected){$req=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::new($method),"$base$path");if($key){$req.Headers.Add('Idempotency-Key',$key)};if($token){$req.Headers.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$token)};if($null -ne $body){$req.Content=[Net.Http.StringContent]::new(($body|ConvertTo-Json -Compress -Depth 30),[Text.Encoding]::UTF8,'application/json')};try{$r=$client.SendAsync($req).GetAwaiter().GetResult();$raw=$r.Content.ReadAsStringAsync().GetAwaiter().GetResult();$v=$null;if($raw){try{$v=$raw|ConvertFrom-Json -Depth 40}catch{$v=$raw}};$trace.Add([ordered]@{method=$method;path=$path;status=[int]$r.StatusCode;code=if($v -and $v.PSObject.Properties.Name -contains 'code'){$v.code}else{$null}});if([int]$r.StatusCode -ne $expected){throw "Product request $method $path rejected HTTP $([int]$r.StatusCode); expected $expected; no raw body logged"};return $v}finally{$req.Dispose()}}
function AdjLogin([string]$login,[string]$password){$page=$member.GetAsync("$base/login").GetAwaiter().GetResult();if([int]$page.StatusCode -ne 200){throw 'Trusted login page unavailable'};$html=$page.Content.ReadAsStringAsync().GetAwaiter().GetResult();$field=[regex]::Match($html,'<input[^>]*name="_csrf"[^>]*>');$csrf=[regex]::Match($field.Value,'value="([^"]+)"');if(-not $csrf.Success){throw 'Normal login CSRF missing'};$form=[Collections.Generic.Dictionary[string,string]]::new();$form.Add('username',$login);$form.Add('password',$password);$form.Add('_csrf',[Net.WebUtility]::HtmlDecode($csrf.Groups[1].Value));$r=$member.PostAsync("$base/login",[Net.Http.FormUrlEncodedContent]::new($form)).GetAwaiter().GetResult();if([int]$r.StatusCode -ne 302 -or $r.Headers.Location.ToString() -match 'error'){throw 'Normal account login failed'};$verifier=[Convert]::ToBase64String([Security.Cryptography.RandomNumberGenerator]::GetBytes(32)).TrimEnd('=').Replace('+','-').Replace('/','_');$challenge=[Convert]::ToBase64String([Security.Cryptography.SHA256]::HashData([Text.Encoding]::ASCII.GetBytes($verifier))).TrimEnd('=').Replace('+','-').Replace('/','_');$callback="$base/app/adjudication";$url="$base/oauth2/authorize?response_type=code&client_id=adjudication-case-workspace&redirect_uri=$([Uri]::EscapeDataString($callback))&scope=openid&state=adj-runtime-validation&code_challenge=$challenge&code_challenge_method=S256";$a=$member.GetAsync($url).GetAwaiter().GetResult();if([int]$a.StatusCode -ne 302){throw 'PKCE authorization did not redirect'};$code=[Web.HttpUtility]::ParseQueryString($a.Headers.Location.Query).Get('code');if(-not $code){throw 'Normal authorization code missing'};$f=[Collections.Generic.Dictionary[string,string]]::new();$f.Add('grant_type','authorization_code');$f.Add('client_id','adjudication-case-workspace');$f.Add('redirect_uri',$callback);$f.Add('code',$code);$f.Add('code_verifier',$verifier);$t=$member.PostAsync("$base/oauth2/token",[Net.Http.FormUrlEncodedContent]::new($f)).GetAwaiter().GetResult();if([int]$t.StatusCode -ne 200){throw 'Normal PKCE exchange failed'};$data=$t.Content.ReadAsStringAsync().GetAwaiter().GetResult()|ConvertFrom-Json;if(-not $data.access_token){throw 'No actual access token'};return $data.access_token}
